# Generated by Django 6.1.2 on 2026-10-19; edited to carry existing targets over.
#
# Category targets switch from monthly to weekly. Existing monthly targets
# are converted (monthly * 12 / 52, rounded, clamped to 1..168) BEFORE the old column is
# dropped, and the reverse migration converts back, so no user's target is
# lost in either direction.

from django.db import migrations, models


def monthly_to_weekly(apps, schema_editor):
    Category = apps.get_model('tracker', 'Category')
    for cat in Category.objects.all().only('id', 'monthly_target_hours'):
        cat.weekly_target_hours = max(1, min(168, round(cat.monthly_target_hours * 12 / 52)))
        cat.save(update_fields=['weekly_target_hours'])


